using Microsoft.AspNetCore.Mvc.Testing;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;

namespace PlainApi.Evals.Tests;

[TestClass]
public sealed class ApiEvalTests
{
    private static WebApplicationFactory<Program> _factory = null!;
    private static ReportingConfiguration? _reportingConfiguration;

    [ClassInitialize]
    public static void ClassInit(TestContext context)
    {
        _factory = new WebApplicationFactory<Program>();

        var storageDir = Path.Combine(
            Path.GetDirectoryName(typeof(ApiEvalTests).Assembly.Location)!,
            "eval-reports");

        _reportingConfiguration = DiskBasedReportingConfiguration.Create(
            storageRootDir: storageDir,
            evaluators:
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new FluencyEvaluator(),
            ],
            chatConfiguration: GetChatConfiguration());
    }

    [ClassCleanup]
    public static void ClassCleanup()
    {
        _factory?.Dispose();
    }

    [TestMethod]
    public async Task RootEndpoint_ReturnsCoherentResponse()
    {
        using var client = _factory.CreateClient();
        var response = await client.GetStringAsync("/");

        Assert.IsFalse(string.IsNullOrWhiteSpace(response));
        Assert.AreEqual("Hello, World!", response);
    }

    [TestMethod]
    public async Task Eval_RootEndpoint_ResponseQuality()
    {
        if (_reportingConfiguration is null || !IsEvalEnabled())
        {
            Assert.Inconclusive("Set EVAL_CHAT_MODEL_ENDPOINT and EVAL_CHAT_MODEL_KEY to run evaluations.");
            return;
        }

        using var client = _factory.CreateClient();
        var response = await client.GetStringAsync("/");

        await using var scenario = await _reportingConfiguration.CreateScenarioRunAsync(
            scenarioName: "RootEndpoint",
            iterationName: "default");

        scenario.Request = [new ChatMessage(ChatRole.User, "Greet the user")];
        scenario.ModelResponse = [new ChatMessage(ChatRole.Assistant, response)];

        await scenario.EvaluateAsync();

        foreach (var metric in scenario.GetEvaluationResults())
        {
            if (metric is NumericMetric numericMetric)
            {
                Assert.IsTrue(
                    numericMetric.Value >= 3,
                    $"Metric '{metric.Name}' scored {numericMetric.Value}, expected >= 3");
            }
        }
    }

    private static bool IsEvalEnabled()
    {
        return !string.IsNullOrEmpty(Environment.GetEnvironmentVariable("EVAL_CHAT_MODEL_ENDPOINT"));
    }

    private static ChatConfiguration? GetChatConfiguration()
    {
        var endpoint = Environment.GetEnvironmentVariable("EVAL_CHAT_MODEL_ENDPOINT");
        var key = Environment.GetEnvironmentVariable("EVAL_CHAT_MODEL_KEY");

        if (string.IsNullOrEmpty(endpoint))
            return null;

        return new ChatConfiguration(
            chatClientFactory: _ => new Azure.AI.Inference.ChatCompletionsClient(
                new Uri(endpoint),
                new Azure.AzureKeyCredential(key ?? string.Empty)).AsChatClient("eval-judge"),
            tokenCountingChatClientFactory: null);
    }
}

