     {
         var endpoint = Environment.GetEnvironmentVariable("EVAL_CHAT_MODEL_ENDPOINT");
         var key = Environment.GetEnvironmentVariable("EVAL_CHAT_MODEL_KEY");
         var model = Environment.GetEnvironmentVariable("EVAL_CHAT_MODEL_NAME") ?? "gpt-4o-mini";

