 using Microsoft.AspNetCore.Mvc.Testing;
 using Microsoft.Extensions.AI;
 using Microsoft.Extensions.AI.Evaluation;
 using Microsoft.Extensions.AI.Evaluation.Quality;
 using Microsoft.Extensions.AI.Evaluation.Reporting;
 using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;

 namespace PlainApi.Evals.Tests;

 [TestClass]
 public sealed class ApiEvalTests
 {
     private static WebApplicationFactory<Program> _factory = null!;
     private static ReportingConfiguration? _reportingConfiguration;

     [ClassInitialize]
     public static void ClassInit(TestContext context)
     {
         _factory = new WebApplicationFactory<Program>();

         var chatConfig = GetChatConfiguration();
         if (chatConfig is null)
             return;

         var storageDir = Path.Combine(
             Path.GetDirectoryName(typeof(ApiEvalTests).Assembly.Location)!,
             "eval-reports");

         _reportingConfiguration = DiskBasedReportingConfiguration.Create(
             storageRootPath: storageDir,
             evaluators:
             [
                 new CoherenceEvaluator(),
                 new RelevanceEvaluator(),
                 new FluencyEvaluator(),
             ],
             chatConfiguration: chatConfig);
     }

     [ClassCleanup]
     public static void ClassCleanup()
     {
         _factory?.Dispose();
     }

     [TestMethod]
     public async Task RootEndpoint_ReturnsExpectedResponse()
     {
         using var client = _factory.CreateClient();
         var response = await client.GetStringAsync("/");

         Assert.IsFalse(string.IsNullOrWhiteSpace(response));
         Assert.AreEqual("Hello, World!", response);
     }

     [TestMethod]
     public async Task Eval_RootEndpoint_ResponseQuality()
     {
         if (_reportingConfiguration is null)
         {
             Assert.Inconclusive(
                 "Set EVAL_CHAT_MODEL_ENDPOINT and EVAL_CHAT_MODEL_KEY to run LLM-judged evaluations.");
             return;
         }

         using var httpClient = _factory.CreateClient();
         var response = await httpClient.GetStringAsync("/");

         await using var scenario = await _reportingConfiguration.CreateScenarioRunAsync(
             scenarioName: "RootEndpoint",
             iterationName: "default");

         var messages = new List<ChatMessage>
         {
             new(ChatRole.User, "Greet the user"),
         };

         var modelResponse = new ChatResponse(new ChatMessage(ChatRole.Assistant, response));

         EvaluationResult result = await scenario.EvaluateAsync(messages, modelResponse);

         foreach (var metric in result.Metrics)
         {
             if (metric.Value is NumericMetric numericMetric)
             {
                 Assert.IsGreaterThanOrEqualTo(
                     numericMetric.Value!.Value, 3.0,
                     $"Metric '{metric.Key}' scored below threshold");
             }
         }
     }

     private static ChatConfiguration? GetChatConfiguration()
     {
         var endpoint = Environment.GetEnvironmentVariable("EVAL_CHAT_MODEL_ENDPOINT");
         var key = Environment.GetEnvironmentVariable("EVAL_CHAT_MODEL_KEY");
         var model = Environment.GetEnvironmentVariable("EVAL_CHAT_MODEL_NAME") ?? "gpt-4o-mini";

         if (string.IsNullOrEmpty(endpoint) || string.IsNullOrEmpty(key))
             return null;

         var openAiClient = new OpenAI.OpenAIClient(
             new System.ClientModel.ApiKeyCredential(key),
             new OpenAI.OpenAIClientOptions { Endpoint = new Uri(endpoint) });

         IChatClient chatClient = openAiClient.GetChatClient(model).AsIChatClient();

         return new ChatConfiguration(chatClient);
     }
 }
